<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Role\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleAllowController;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleListController;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleCreateController;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleRetrieveController;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleUpdateController;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driver\Rest\RoleDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\Role\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Create\RoleCreateAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Update\RoleUpdateAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Retrieve\RoleRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\List\RoleListAllowDecision;
use Civi\Lughauth\Features\Access\Role\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\Role\Application\Usecase\Delete\RoleDeleteAllowDecision;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driven\RoleReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\Role\Infrastructure\Driven\RoleWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\Role\Domain\Gateway\RoleReadGateway;
use Civi\Lughauth\Features\Access\Role\Domain\Gateway\RoleWriteGateway;

class RolePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[RoleReadGateway::class] = \DI\autowire(RoleReadRepositoryAdapter::class);
        $def[RoleWriteGateway::class] = \DI\autowire(RoleWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/roles', [$this, 'setRoutesForRole']);
        $collector->group('/api/me/acl/access/roles', [$this, 'setRoutesForRoleAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(RoleCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(RoleUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(RoleRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(RoleListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(RoleDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("role", "list", "READ");
            $handler->registerResourceAction("role", "create", "WRITE");
            $handler->registerResourceAction("role", "retrieve", "READ");
            $handler->registerResourceAction("role", "update", "WRITE");
            $handler->registerResourceAction("role", "delete", "WRITE");

            $handler->registerResourceAttribute("role", "name", "MANAGE");
            $handler->registerResourceAttribute("role", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("role", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForRoleAcl(RouteCollectorProxy $roleGroup): void
    {
        $roleGroup->get('', [RoleAllowController::class, 'genericAllow']);
        $roleGroup->get('/{uid}', [RoleAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForRole(RouteCollectorProxy $roleGroup): void
    {
        $roleGroup->get('', [RoleListController::class, 'list']);
        $roleGroup->post('', [RoleCreateController::class, 'create']);
        $roleGroup->get('/{uid}', [RoleRetrieveController::class, 'retrieve']);
        $roleGroup->put('/{uid}', [RoleUpdateController::class, 'update']);
        $roleGroup->delete('/{uid}', [RoleDeleteController::class, 'delete']);
        $roleGroup->delete('', [RoleDeleteController::class, 'deleteAllForQuery']);
        $roleGroup->get('/~/delete-status/{uid}', [RoleDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
